preview.css:
html,
body {
  margin: 0;
  padding: 0;
  background: transparent;
  width: 100%;
  min-height: 104px;
  overflow: visible;
}

:root {
  --glow-follow-rgb: 255, 77, 141;
  --glow-sub-rgb: 42, 189, 255;
  --glow-cheer-rgb: 255, 27, 223;
  --glow-tip-rgb: 87, 27, 195;
}

/* Layout */
.labels-row {
  display: flex;
  align-items: center;
  justify-content: space-evenly;
  width: 100%;
  min-height: 104px;
  padding: 40px 24px;
  box-sizing: border-box;
  white-space: nowrap;
}

/* Bloc */
.label-box {
  width: 194px;
  height: 24px;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 10px;
  border-radius: 3px;
  background: rgba(0, 0, 0, 0);

  filter:
    drop-shadow(0px 1px 0px rgba(89, 0, 255, 1))
    drop-shadow(0px 2px 0px rgba(23, 9, 228, 1));
}

/* Icône (conteneur 24x24 centré) */
.icon {
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Material icon (glyph) */
.material-symbols-sharp {
  font-family: "Material Symbols Sharp";
  font-variation-settings:
    "FILL" 1,
    "wght" 200,
    "GRAD" 0,
    "opsz" 24;

  font-size: 24px;
  line-height: 1;
  display: block;
  color: inherit;
}

/* Texte */
.txt {
  width: 160px;
  /* Étend la zone de clipping vertical sans déplacer ni agrandir le label. */
  padding-block: 36px;
  margin-block: -36px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1;
}

/* ===== Glows par type (texte + icône) ===== */
.box-follow { --label-glow-rgb: var(--glow-follow-rgb); }
.box-sub    { --label-glow-rgb: var(--glow-sub-rgb); }
.box-cheer  { --label-glow-rgb: var(--glow-cheer-rgb); }
.box-tip    { --label-glow-rgb: var(--glow-tip-rgb); }

/* L'icône ne possède pas d'overflow : text-shadow peut rester utilisé. */
.label-box .material-symbols-sharp {
  text-shadow:
    0 0 1px  rgba(var(--label-glow-rgb), 0.85),
    0 0 4.5px rgba(var(--label-glow-rgb), 0.62),
    0 0 10px rgba(var(--label-glow-rgb), 0.36),
    0 0 20px rgba(var(--label-glow-rgb), 0.15);
}

/*
  Le texte doit conserver overflow:hidden pour l'ellipse. Un text-shadow serait
  découpé par cet overflow ; drop-shadow est calculé après le découpage du texte
  et peut donc rayonner à l'extérieur de la zone de 160 px.
*/
.label-box .txt {
  text-shadow: none;
  filter:
    drop-shadow(0 0 1px rgba(var(--label-glow-rgb), 0.8))
    drop-shadow(0 0 3px rgba(var(--label-glow-rgb), 0.58))
    drop-shadow(0 0 6px rgba(var(--label-glow-rgb), 0.34))
    drop-shadow(0 0 12px rgba(var(--label-glow-rgb), 0.15));
}

/* =========================
   Réglages synchro vidéo
   (t0 et tEnd sont "baked" dans les keyframes en %)
========================= */
:root{
  --cycle: 40s;     /* boucle vidéo */
  --slide: 24px;
}

/* Base anim */
.label-box .icon,
.label-box .txt{
  opacity: 0;
  transform: translateY(var(--slide));
  will-change: opacity, transform;

  animation-duration: var(--cycle);
  animation-iteration-count: infinite;
  animation-fill-mode: both;
  animation-timing-function: ease, ease;
}

/* =========================================================
   ICON — MOVE (long) + FADE (rapide)
   Fenêtre vidéo: 8.96s -> ~28.20s
   (% calculés sur 40s)
========================================================= */

/* Transform (monte plus lentement) */
@keyframes kIconMove40 {
  0%, 22.40% { transform: translateY(var(--slide)); } /* avant t0 */
  25.03%     { transform: translateY(0); }            /* fin montée */
  68.00%     { transform: translateY(0); }            /* hold */
  70.50%     { transform: translateY(var(--slide)); } /* descente */
  100%       { transform: translateY(var(--slide)); }
}

/* Opacity (arrive à 1 AVANT la fin du move) */
@keyframes kIconFade40 {
  0%, 22.40% { opacity: 0; }

  /* fade in rapide, pendant que ça monte encore */
  22.85%     { opacity: 1; }

  /* hold */
  69.20%     { opacity: 1; }

  /* fade out pendant la descente */
  70.50%     { opacity: 0; }

  100%       { opacity: 0; }
}

/* =========================================================
   TEXT — MOVE + FADE (décalé vs icône)
========================================================= */

@keyframes kTextMove40 {
  0%, 22.60% { transform: translateY(var(--slide)); }
  25.15%     { transform: translateY(0); }
  68.13%     { transform: translateY(0); }
  70.63%     { transform: translateY(var(--slide)); }
  100%       { transform: translateY(var(--slide)); }
}

@keyframes kTextFade40 {
  0%, 22.60% { opacity: 0; }

  /* opacité à 1 avant la fin du slide up */
  23.10%     { opacity: 1; }

  69.33%     { opacity: 1; }
  70.63%     { opacity: 0; }

  100%       { opacity: 0; }
}

/* ===== Application : 2 animations en parallèle (move + fade) ===== */
#colFollow .icon{
  animation-name: kIconMove40, kIconFade40;
  animation-delay: 0s, 0s;
}
#colSub .icon{
  animation-name: kIconMove40, kIconFade40;
  animation-delay: 0.32s, 0.32s;
}
#colCheer .icon{
  animation-name: kIconMove40, kIconFade40;
  animation-delay: 0.64s, 0.64s;
}
#colTip .icon{
  animation-name: kIconMove40, kIconFade40;
  animation-delay: 0.96s, 0.96s;
}

#colFollow .txt{
  animation-name: kTextMove40, kTextFade40;
  animation-delay: 0s, 0s;
}
#colSub .txt{
  animation-name: kTextMove40, kTextFade40;
  animation-delay: 0.32s, 0.32s;
}
#colCheer .txt{
  animation-name: kTextMove40, kTextFade40;
  animation-delay: 0.64s, 0.64s;
}
#colTip .txt{
  animation-name: kTextMove40, kTextFade40;
  animation-delay: 0.96s, 0.96s;
}

/*
  Le cycle de production reste synchronisé avec la vidéo (apparition vers 9 s).
  Le laboratoire ajoute cette classe à l'iframe pour positionner immédiatement
  l'aperçu dans la partie visible du cycle. StreamElements n'ajoute pas la classe.
*/
html.se-lab-preview #colFollow :is(.icon, .txt) {
  animation-delay: -10s, -10s;
}

html.se-lab-preview #colSub :is(.icon, .txt) {
  animation-delay: -9.68s, -9.68s;
}

html.se-lab-preview #colCheer :is(.icon, .txt) {
  animation-delay: -9.36s, -9.36s;
}

html.se-lab-preview #colTip :is(.icon, .txt) {
  animation-delay: -9.04s, -9.04s;
}

