function clamp(n, min, max){ return Math.max(min, Math.min(max, n)); }
function num(v){
  const s = String(v ?? "").trim().replace(",", ".");
  const n = Number(s.replace(/[^\d.-]/g,''));
  return Number.isFinite(n) ? n : 0;
}

const iconMap = {
  follows: "favorite",
  subs: "star_shine",
  cheers: "diamond_shine",
  tips: "money_bag"
};

let SETTINGS = {};
let SESSION = null;
let lastCurrent = null;
let lastComplete = null;

// Bases (auto StreamElements) + incréments live
let subsBase = 0, subsAdded = 0;
let followsBase = 0, followsAdded = 0;
let cheersBase = 0, cheersAdded = 0;
let tipsBase = 0, tipsAdded = 0;

// ------------------------------------
// Google Fonts
// ------------------------------------
function setGoogleFont(family){
  const link = document.getElementById("googleFontLink");
  if (!link) return;

  const name = String(family || "Inter").trim();
  const urlName = name.replace(/\s+/g, "+");
  link.href = `https://fonts.googleapis.com/css2?family=${urlName}:wght@300;400;500;600;700;800&display=swap`;
  document.documentElement.style.setProperty("--font", `"${name}"`);
}

// ------------------------------------
// Couleurs (uni / dégradé)
// ------------------------------------
function isHexColor(v){
  const s = String(v ?? "").trim();
  if (!/^#[0-9a-f]+$/i.test(s)) return false;
  const len = s.length - 1;
  return len === 3 || len === 6 || len === 8;
}
function normalizeColorValue(v){
  const s = String(v ?? "").trim();
  if (!s) return null;
  if (isHexColor(s)){
    const hex = s.slice(1);
    if (hex.length === 3) return "#" + hex.split("").map(c => c + c).join("");
    if (hex.length === 8) return "#" + hex.slice(0, 6);
    return "#" + hex;
  }
  if (/^(rgb|hsl)a?\(/i.test(s)) return s;
  return null;
}
function hexOr(v, fallback){
  return normalizeColorValue(v) ?? fallback;
}
function hexToRgb(hexValue){
  const clean = String(hexValue ?? "#ffffff").trim().replace("#", "");
  const full = clean.length === 3 ? clean.split("").map(c => c + c).join("") : clean;
  const n = parseInt(full, 16);
  if (full.length !== 6 || !Number.isFinite(n)) return { r: 255, g: 255, b: 255 };
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}
function toRgba(hexValue, alpha){
  const { r, g, b } = hexToRgb(hexValue);
  return `rgba(${r}, ${g}, ${b}, ${clamp(alpha, 0, 1)})`;
}
function buildPaint(type, color1, color2, angle, alpha){
  const c1 = alpha === undefined ? color1 : toRgba(color1, alpha);
  const c2 = alpha === undefined ? color2 : toRgba(color2, alpha);
  return type === "gradient" ? `linear-gradient(${angle}deg, ${c1}, ${c2})` : c1;
}

// ------------------------------------
// Forme du croissant (tracé exact fourni par le design, mis à l'échelle)
// ------------------------------------
function buildCrescentPath(totalWidthPx, totalHeightPx){
  const s = totalHeightPx / 24;
  const n = (v) => +(v * s).toFixed(3);
  const capW = n(21);
  const rightStart = +(totalWidthPx - capW).toFixed(3);

  return (
    `M${rightStart},${n(18)}` +
    `H${capW}` +
    `C${n(10.47)},${n(18)} ${n(1.71)},${n(10.14)} ${n(0.24)},0` +
    `c${n(-0.14)},${n(0.98)} ${n(-0.24)},${n(1.98)} ${n(-0.24)},${n(3)}` +
    `c0,${n(11.55)} ${n(9.45)},${n(21)} ${n(21)},${n(21)}` +
    `H${rightStart}` +
    `c${n(11.55)},0 ${n(21)},${n(-9.45)} ${n(21)},${n(-21)}` +
    `c0,${n(-1.02)} ${n(-0.1)},${n(-2.02)} ${n(-0.24)},${n(-3)}` +
    `c${n(-1.47)},${n(10.14)} ${n(-10.23)},${n(18)} ${n(-20.76)},${n(18)}` +
    `Z`
  );
}

// ------------------------------------
// Normalize helpers
// ------------------------------------
function isGoalType(v){
  const s = String(v ?? "").toLowerCase();
  return s === "follows" || s === "subs" || s === "tips" || s === "cheers";
}
function isColorType(v){
  const s = String(v ?? "").toLowerCase();
  return s === "solid" || s === "gradient";
}

// ------------------------------------
// Normalisation du fieldData nommé fourni par StreamElements
// ------------------------------------
function normalizeFields(raw){
  if (Array.isArray(raw)){
    raw = Object.fromEntries(raw.filter(field => field?.name).map(field => [field.name, field.value]));
  }
  raw = raw || {};

  return {
    font_family: String(raw.font_family ?? "Poppins"),
    font_weight: String(raw.font_weight ?? "500"),
    text_size: num(raw.text_size ?? 14),
    width: num(raw.width ?? 400),
    height: num(raw.height ?? 46),

    border_color: hexOr(raw.border_color, "#ffffff"),
    border_width: Math.max(0, num(raw.border_width ?? 1)),
    border_opacity: clamp(num(raw.border_opacity ?? 1), 0, 1),
    background_type: isColorType(raw.background_type) ? String(raw.background_type) : "gradient",
    background_color1: hexOr(raw.background_color1, "#161225"),
    background_color2: hexOr(raw.background_color2, "#231a3d"),
    background_opacity: clamp(num(raw.background_opacity ?? 1), 0, 1),

    follows_color_type: isColorType(raw.follows_color_type) ? String(raw.follows_color_type) : "solid",
    follows_color1: hexOr(raw.follows_color1, "#ff4d8d"),
    follows_color2: hexOr(raw.follows_color2, "#ff4d8d"),

    subs_color_type: isColorType(raw.subs_color_type) ? String(raw.subs_color_type) : "solid",
    subs_color1: hexOr(raw.subs_color1, "#2abdff"),
    subs_color2: hexOr(raw.subs_color2, "#2abdff"),

    cheers_color_type: isColorType(raw.cheers_color_type) ? String(raw.cheers_color_type) : "solid",
    cheers_color1: hexOr(raw.cheers_color1, "#ff1bdf"),
    cheers_color2: hexOr(raw.cheers_color2, "#ff1bdf"),

    tips_color_type: isColorType(raw.tips_color_type) ? String(raw.tips_color_type) : "solid",
    tips_color1: hexOr(raw.tips_color1, "#571bc3"),
    tips_color2: hexOr(raw.tips_color2, "#571bc3"),

    goal_type: isGoalType(raw.goal_type) ? String(raw.goal_type) : "tips",
    title: String(raw.title ?? "Donation goal"),
    goal_total: Math.max(1, num(raw.goal_total ?? 500))
  };
}

function refreshSettingsFromFieldData(raw){
  SETTINGS = normalizeFields(raw || {}) || {};
}

function getSetting(key, fallback){
  return (SETTINGS && SETTINGS[key] != null) ? SETTINGS[key] : fallback;
}

// ------------------------------------
// Totaux session (AUTO StreamElements)
// ------------------------------------
function pickFirstNumber(...vals){
  for (const v of vals){
    if (v !== undefined && v !== null && v !== "") return num(v);
  }
  return null;
}

function readTotalsFromSession(session){
  const s = session || {};
  const d = s?.data || s || {};
  const follows = pickFirstNumber(
    d?.["follower-total"]?.count,
    d?.["followers-total"]?.count,
    d?.["follower-count"]?.count
  );

  const subs = pickFirstNumber(
    d?.["subscriber-total"]?.count,
    d?.["subscriber-count"]?.count,
    d?.["subscribers-count"]?.count,
    d?.["subscriber-points"]?.amount,
    d?.["subscriber-points"]?.count
  );

  const cheers = pickFirstNumber(
    d?.["cheer-total"]?.amount,
    d?.["cheer-total"]?.count
  );

  const tips = pickFirstNumber(
    d?.["tip-total"]?.amount,
    d?.["tips-total"]?.amount
  );

  return { follows, subs, cheers, tips };
}

// ------------------------------------
// Values
// ------------------------------------
function getCurrentValue(type){
  if (type === "follows") return followsBase + followsAdded;
  if (type === "subs")    return subsBase + subsAdded;
  if (type === "tips")    return tipsBase + tipsAdded;
  if (type === "cheers")  return cheersBase + cheersAdded;
  return 0;
}

// ------------------------------------
// Fill
// ------------------------------------
let fillObserverStarted = false;

function bump(el){
  if (!el) return;
  el.classList.remove("is-bump");
  void el.offsetWidth;
  el.classList.add("is-bump");
}

function spawnConfetti(container){
  if (!container) return;

  const count = 16;
  for (let i = 0; i < count; i += 1){
    const angle = (Math.PI * 2 * i) / count + (Math.random() * 0.6 - 0.3);
    const distance = 34 + Math.random() * 46;

    const piece = document.createElement("span");
    piece.className = "goal-confetti";
    piece.style.setProperty("--tx", `${Math.cos(angle) * distance}px`);
    piece.style.setProperty("--ty", `${Math.sin(angle) * distance - 16}px`);
    piece.style.setProperty("--rot", `${Math.round(Math.random() * 360)}deg`);
    piece.style.animationDelay = `${Math.random() * 90}ms`;
    piece.style.width = piece.style.height = `${4 + Math.random() * 4}px`;
    if (Math.random() > 0.5) piece.style.borderRadius = "50%";

    container.appendChild(piece);
    piece.addEventListener("animationend", () => piece.remove());
  }
}

function celebrate(el){
  if (!el) return;
  el.classList.remove("is-complete");
  void el.offsetWidth;
  el.classList.add("is-complete");
  spawnConfetti(el);
}

function animateValueRoll(el, mask, previousText){
  if (!el || !mask) return;

  const ghost = document.createElement("span");
  ghost.className = "goal-value-ghost";
  ghost.textContent = previousText;
  mask.insertBefore(ghost, el);
  ghost.addEventListener("animationend", () => ghost.remove());

  el.classList.remove("is-entering");
  void el.offsetWidth;
  el.classList.add("is-entering");
}

function applyFillWidth(safePct){
  const progressWindow = document.getElementById("progressWindow");
  const fillEl = document.getElementById("fill");
  const goalEl = document.getElementById("goal");
  if (!progressWindow || !fillEl || !goalEl) return;

  progressWindow.style.width = safePct + "%";

  const setShapeIfPossible = () => {
    const fullWidthPx = goalEl.clientWidth;
    if (fullWidthPx && fullWidthPx >= 10){
      fillEl.style.width = fullWidthPx + "px";
      fillEl.style.clipPath = `path("${buildCrescentPath(fullWidthPx, 24)}")`;
      return true;
    }
    return false;
  };

  if (!setShapeIfPossible()){
    requestAnimationFrame(setShapeIfPossible);
  }

  if (!fillObserverStarted && typeof ResizeObserver !== "undefined"){
    fillObserverStarted = true;
    const ro = new ResizeObserver(() => setShapeIfPossible());
    ro.observe(goalEl);
  }
}

// ------------------------------------
// Render
// ------------------------------------
function update(){
  if (!SETTINGS) SETTINGS = {};

  const type      = String(getSetting("goal_type", "tips"));
  const target    = num(getSetting("goal_total", 500));
  const title     = String(getSetting("title", "Donation goal"));

  const w         = num(getSetting("width", 400));
  const h         = num(getSetting("height", 46));
  const ff        = String(getSetting("font_family", "Poppins"));
  const fw        = String(getSetting("font_weight", "500"));
  const textSize  = num(getSetting("text_size", 14));

  setGoogleFont(ff);
  document.documentElement.style.setProperty("--textWeight", fw);

  document.documentElement.style.setProperty("--w", w > 0 ? w + "px" : "100%");
  if (h > 0) document.documentElement.style.setProperty("--h", h + "px");
  if (textSize > 0) document.documentElement.style.setProperty("--textSize", textSize + "px");

  const borderColor = String(getSetting("border_color", "#ffffff"));
  const borderWidth = Math.max(0, num(getSetting("border_width", 1)));
  const borderOpacity = clamp(num(getSetting("border_opacity", 1)), 0, 1);
  document.documentElement.style.setProperty("--border-color", toRgba(borderColor, borderOpacity));
  document.documentElement.style.setProperty("--border-width", borderWidth + "px");

  const bgType = String(getSetting("background_type", "gradient"));
  const bgColor1 = String(getSetting("background_color1", "#161225"));
  const bgColor2 = String(getSetting("background_color2", "#231a3d"));
  const bgOpacity = clamp(num(getSetting("background_opacity", 1)), 0, 1);
  document.documentElement.style.setProperty("--bg", buildPaint(bgType, bgColor1, bgColor2, 135, bgOpacity));

  const progressType = String(getSetting(`${type}_color_type`, "solid"));
  const progressColor1 = String(getSetting(`${type}_color1`, "#571bc3"));
  const progressColor2 = String(getSetting(`${type}_color2`, progressColor1));
  const progressPaint = progressType === "gradient"
    ? buildPaint(progressType, progressColor2, progressColor1, 90)
    : buildPaint(progressType, progressColor1, progressColor2, 90);
  document.documentElement.style.setProperty("--progress-bg", progressPaint);
  document.documentElement.style.setProperty("--progress-glow", toRgba(progressColor1, 1));

  const titleEl = document.getElementById("title");
  if (titleEl) titleEl.textContent = title;

  const iconEl = document.getElementById("goalIcon");
  if (iconEl) iconEl.textContent = iconMap[type] || "money_bag";

  const current = getCurrentValue(type);
  const suffix = (type === "tips") ? "€" : "";

  const curEl = document.getElementById("current");
  const curMask = document.getElementById("currentMask");
  const tarEl = document.getElementById("target");
  const previousCurrentText = curEl ? curEl.textContent : "";
  if (curEl) curEl.textContent = suffix ? `${current}${suffix}` : `${current}`;
  if (tarEl) tarEl.textContent = suffix ? `${target}${suffix}` : `${target}`;

  if (lastCurrent !== null && current !== lastCurrent){
    bump(document.getElementById("goalIconWrap"));
    animateValueRoll(curEl, curMask, previousCurrentText);
  }
  lastCurrent = current;

  const isComplete = target > 0 && current >= target;
  const goalEl = document.getElementById("goal");
  if (lastComplete === false && isComplete){
    celebrate(goalEl);
  } else if (goalEl){
    if (isComplete) goalEl.classList.add("is-complete");
    else goalEl.classList.remove("is-complete");
  }
  lastComplete = isComplete;

  const pct = target > 0 ? (current / target) * 100 : 0;
  applyFillWidth(clamp(pct, 0, 100));
}

// ------------------------------------
// DEDUPE
// ------------------------------------
const SEEN = new Map();
const DEDUPE_MS = 6000;

function cleanupSeen(){
  const now = Date.now();
  for (const [k, t] of SEEN.entries()){
    if (now - t > DEDUPE_MS) SEEN.delete(k);
  }
}

function eventKey(listener, ev){
  const id = ev?.id ?? ev?._id ?? ev?.eventId ?? ev?.data?.id ?? ev?.data?._id ?? ev?.data?.eventId;
  if (id != null) return `id:${id}`;

  const type = String(ev?.type ?? "");
  const user = ev?.name ?? ev?.username ?? ev?.displayName ?? ev?.data?.name ?? ev?.data?.username ?? "";
  const amount =
    ev?.amount ?? ev?.data?.amount ?? ev?.data?.tipAmount ?? ev?.data?.donationAmount ??
    ev?.data?.count ?? ev?.count ?? ev?.data?.amountGifted ?? ev?.data?.bits ?? "";

  return `sig:${String(listener)}|${type}|${String(user)}|${String(amount)}`;
}

function shouldProcess(listener, ev){
  cleanupSeen();
  const key = eventKey(listener, ev);
  if (SEEN.has(key)) return false;
  SEEN.set(key, Date.now());
  return true;
}

// ------------------------------------
// Events
// ------------------------------------
function handleEvent(obj){
  const listener = String(obj?.detail?.listener || "").toLowerCase();
  const ev = obj?.detail?.event || null;
  if (!ev) return;

  if (!shouldProcess(listener, ev)) return;

  const type = String(ev.type || "").toLowerCase();

  // FOLLOW
  if (type === "follow" || listener.includes("follower")){
    followsAdded += 1;
    update();
    return;
  }

  // TIPS
  const isTip =
    type.includes("tip") || type.includes("donation") ||
    listener.includes("tip") || listener.includes("donation");

  if (isTip){
    const amount = num(
      ev.amount ??
      ev.tipAmount ??
      ev.donationAmount ??
      ev.total ??
      ev?.data?.amount ??
      ev?.data?.tipAmount ??
      ev?.data?.donationAmount ??
      ev?.data?.total ??
      0
    );

    if (amount > 0){
      tipsAdded += amount;
      update();
    }
    return;
  }

  // CHEERS / BITS
  const isCheer =
    type.includes("cheer") || type.includes("bits") || type.includes("bit") ||
    listener.includes("cheer") || listener.includes("bits");

  if (isCheer){
    const bits = num(
      ev.amount ??
      ev.bits ??
      ev?.data?.amount ??
      ev?.data?.bits ??
      ev?.data?.total ??
      0
    );

    if (bits > 0){
      cheersAdded += bits;
      update();
    }
    return;
  }

  // SUBS
  const looksLikeSub =
    listener.includes("sub") || listener.includes("subscriber") || listener.includes("subscription") ||
    type.includes("sub") || type.includes("subscriber") || type.includes("subscription") || type.includes("resub");

  const looksLikeGift =
    listener.includes("gift") || type.includes("gift") || type.includes("communitygift") || type.includes("subgift");

  if (looksLikeGift){
    const count = num(
      ev?.data?.amount ??
      ev?.data?.count ??
      ev?.data?.gifted ??
      ev?.data?.amountGifted ??
      ev?.amount ??
      ev?.count ??
      1
    );
    subsAdded += Math.max(1, count);
    update();
    return;
  }

  if (looksLikeSub){
    subsAdded += 1;
    update();
  }
}

// ------------------------------------
// Init
// ------------------------------------
function boot(rawFieldData){
  refreshSettingsFromFieldData(rawFieldData);
  const totals = readTotalsFromSession(SESSION);

  followsBase = totals.follows ?? followsBase ?? 0;
  cheersBase = totals.cheers ?? cheersBase ?? 0;
  subsBase = totals.subs ?? subsBase ?? 0;
  tipsBase = totals.tips ?? tipsBase ?? 0;

  followsAdded = 0;
  subsAdded = 0;
  cheersAdded = 0;
  tipsAdded = 0;

  update();
  requestAnimationFrame(update);
}

window.addEventListener("onWidgetLoad", (obj) => {
  SESSION = obj?.detail?.session || null;
  boot(obj?.detail?.fieldData || {});
});

window.addEventListener("onWidgetUpdate", (obj) => {
  boot(obj?.detail?.fieldData || {});
});

window.addEventListener("onSessionUpdate", (obj) => {
  const sess = obj?.detail?.session;
  if (!sess) return;

  SESSION = sess;
  const totals = readTotalsFromSession(SESSION);

  if (totals.follows !== null){
    followsBase = totals.follows;
    followsAdded = 0;
  }
  if (totals.cheers !== null){
    cheersBase = totals.cheers;
    cheersAdded = 0;
  }
  if (totals.subs !== null){
    subsBase = totals.subs;
    subsAdded = 0;
  }
  if (totals.tips !== null){
    tipsBase = totals.tips;
    tipsAdded = 0;
  }

  update();
});

window.addEventListener("onEventReceived", (obj) => {
  handleEvent(obj);
});

preview.css:
@import url("https://fonts.googleapis.com/css2?family={fontFamily}:wght@300;400;500;600&display=swap");

:root {
  --font-family: "{fontFamily}", sans-serif;
  --font-size: {fontSize}px;
  --font-weight: {fontWeight};
  --text-color: {textColor};
  --bubble-background: {bubbleBackground};
  --bubble-background-2: {bubbleBackground2};
  --bubble-background-alpha: var(--bubble-background);
  --bubble-background-2-alpha: var(--bubble-background-2);
  --message-spacing: {messageSpacing}px;
  --pointer-gap: {pointerGap}px;
  --glow-size: {glowSize}px;
  --animation-duration: {animationDuration}ms;
  --entry-easing: cubic-bezier(0.4, 0, 0.2, 1);

  --padding-y: 0.55rem;
  --padding-x: 0.9rem;
  --radius: 14px;
  --row-gap: var(--pointer-gap);
  --line-height: 1.3;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent;
}

body {
  color: var(--text-color);
  font-family: var(--font-family);
  font-size: var(--font-size);
  font-weight: var(--font-weight);
}

#chat {
  position: absolute;
  inset: 18px 24px 18px 18px;

  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: var(--message-spacing);

  overflow: visible;
}

/* Toggled by messagePosition="top" — anchors the stack to the top of the
   screen instead of the bottom. Messages keep their normal chronological
   order (oldest on top, newest on the bottom of the stack, still entering
   from below) — only the anchor point of the whole group moves. */
#chat.is-top {
  justify-content: flex-start;
}

.chat-row {
  display: flex;
  flex: 0 0 auto;
  align-items: flex-start;
  align-self: flex-start;
  gap: var(--row-gap);
  max-width: 100%;

}

.chat-row.is-broadcaster {
  width: 100%;
  flex-direction: row-reverse;
  justify-content: flex-start;
  align-self: stretch;
}

.identity,
.message-bubble {
  min-width: 0;
  padding: var(--padding-y) var(--padding-x);

  color: var(--text-color);
  font: inherit;
  line-height: var(--line-height);
  border: 1px solid;
  border-radius: var(--radius);
}

.identity {
  position: relative;

  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 0.3em;

  overflow: hidden;
  white-space: nowrap;
  background:
    linear-gradient(105deg, var(--role-start-soft), var(--role-end-soft));
  border-color: var(--identity-border);
  box-shadow:
    0 2px 8px rgba(0, 0, 0, 0.28),
    0 0 var(--glow-size) var(--glow-color);
  backdrop-filter: blur(3px);
  /* Squared on the side that touches the message bubble, so the two chips
     read as one continuous shape along the shared top edge instead of a
     rounded notch — mirrored below for the reversed broadcaster layout. */
  border-top-right-radius: 0;

  animation:
    identity-in var(--animation-duration) var(--entry-easing) both,
    fade-in var(--animation-duration) linear both;
}

.chat-row.is-broadcaster .identity {
  border-top-right-radius: var(--radius);
  border-top-left-radius: 0;

  animation-name: identity-in-broadcaster, fade-in;
}

.username {
  overflow: hidden;
  max-width: 145px;
  text-overflow: ellipsis;
}

.badges {
  display: inline-flex;
  align-items: center;
  gap: 0.22em;
  line-height: 1;
}

.badge {
  display: block;
  flex: 0 0 auto;
  width: 1em;
  height: 1em;
  object-fit: contain;
}

.message-bubble {
  position: relative;

  flex: 0 1 auto;
  overflow-wrap: anywhere;
  background: linear-gradient(105deg, var(--bubble-background-alpha), var(--bubble-background-2-alpha));
  border-color: var(--message-border);
  box-shadow:
    0 4px 14px rgba(0, 0, 0, 0.22),
    0 0 var(--glow-size) var(--glow-color);
  backdrop-filter: blur(3px);
  /* Squared on the side that touches the identity chip — see .identity. */
  border-top-left-radius: 0;

  animation:
    bubble-in var(--animation-duration) var(--entry-easing) max(0ms, calc(var(--animation-duration) - 140ms)) both,
    fade-in var(--animation-duration) linear max(0ms, calc(var(--animation-duration) - 140ms)) both;
}

.chat-row.is-broadcaster .message-bubble {
  border-top-left-radius: var(--radius);
  border-top-right-radius: 0;

  animation-name: bubble-in-broadcaster, fade-in;
}

.message-content {
  white-space: pre-wrap;
}

.emote {
  display: inline-block;
  width: auto;
  height: 1.25em;
  margin: -0.15em 0.08em;
  vertical-align: middle;
  object-fit: contain;
}

.message-content.is-emote-only .emote {
  height: 2.4em;
  margin-block: -0.55em;
}

.tone {
  position: absolute;
  z-index: 2;
  top: -0.55em;
  right: -0.8em;

  display: block;
  width: 1.45em;
  height: 1.45em;

  pointer-events: none;
  object-fit: contain;

  transform-origin: center;
  animation:
    tone-in calc(var(--animation-duration) + 180ms) cubic-bezier(0.18, 1.45, 0.35, 1) calc(var(--animation-duration) + 120ms) both,
    tone-idle 1.8s ease-in-out calc(var(--animation-duration) + var(--animation-duration) + 300ms) infinite alternate;
}

.chat-row.is-broadcaster .tone {
  right: auto;
  left: -0.8em;
}

.chat-row.is-leaving {
  pointer-events: none;
  animation: message-out var(--animation-duration) ease-in both;
}

@keyframes identity-in {
  from {
    transform: translateX(-24px);
  }

  to {
    transform: translateX(0);
  }
}

@keyframes identity-in-broadcaster {
  from {
    transform: translateX(24px);
  }

  to {
    transform: translateX(0);
  }
}

@keyframes bubble-in {
  from {
    transform: translateX(-24px);
  }

  to {
    transform: translateX(0);
  }
}

@keyframes bubble-in-broadcaster {
  from {
    transform: translateX(24px);
  }

  to {
    transform: translateX(0);
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes tone-in {
  0% {
    opacity: 0;
    transform: translateY(-9px) rotate(-24deg) scale(0.15);
  }

  68% {
    opacity: 1;
    transform: translateY(1px) rotate(9deg) scale(1.28);
  }

  100% {
    opacity: 1;
    transform: translateY(0) rotate(-3deg) scale(1);
  }
}

@keyframes tone-idle {
  from {
    transform: translateY(0) rotate(-4deg);
  }

  to {
    transform: translateY(-2px) rotate(5deg);
  }
}

@keyframes message-out {
  to {
    opacity: 0;
    transform: translateY(-6px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .chat-row,
  .identity,
  .message-bubble,
  .tone {
    animation-duration: 1ms;
    animation-iteration-count: 1;
  }
}

preview.js:
const chat = document.querySelector("#chat");

let fields = {};
let ignoredUsers = new Set();

const testMessages = [
  {
    displayName: "Luna",
    badges: [],
    text: "Salut tout le monde !"
  },
  {
    displayName: "NovaMod",
    badges: [{
      type: "moderator",
      version: "1",
      url: "https://static-cdn.jtvnw.net/badges/v1/3267646d-33f0-4b17-b3df-f923a41db1d0/3",
      description: "Modérateur"
    }],
    text: "Le message de test fonctionne parfaitement."
  },
  {
    displayName: "VeryLongViewerName",
    badges: [],
    text: "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Vestibulum cursus dignissim turpis quis efficitur. Phasellus fermentum et libero vitae placerat."
  },
  {
    displayName: "PixelVIP",
    badges: [{
      type: "vip",
      version: "1",
      url: "https://static-cdn.jtvnw.net/badges/v1/b817aba4-fad8-49e2-b88a-7cc744dfa6ec/3",
      description: "VIP"
    }],
    text: "Cette bulle est un peu plus longue pour vérifier le retour à la ligne et les espacements."
  },
  {
    displayName: "Arty",
    badges: [{
      type: "artist-badge",
      version: "1",
      url: "https://static-cdn.jtvnw.net/badges/v1/4300a897-03dc-4e83-8c0e-c332fee7057f/3",
      description: "Artiste"
    }],
    text: "On valide cette version ?"
  },
  {
    displayName: "MaChaine",
    badges: [{
      type: "broadcaster",
      version: "1",
      url: "https://static-cdn.jtvnw.net/badges/v1/5527c58c-fb7d-422d-b71b-f309dcb85cc1/3",
      description: "Streamer"
    }],
    text: "Message du Broadcaster, avec la disposition inversée !"
  }
];

let nextTestMessage = 0;

window.addEventListener("onWidgetLoad", ({ detail }) => {
  fields = detail?.fieldData || {};
  ignoredUsers = new Set(
    String(fields.ignoredUsers || "")
      .split(",")
      .map((name) => name.trim().toLowerCase())
      .filter(Boolean)
  );
  chat.classList.toggle("is-top", fields.messagePosition === "top");
  applyGlobalTheme();
  window.requestAnimationFrame(trimToLimit);
});

window.addEventListener("onEventReceived", ({ detail }) => {
  const event = detail?.event || {};
  const listener = detail?.listener || event.listener;
  const isWidgetButton = detail?.listener === "widget-button" || event.listener === "widget-button";

  if (isWidgetButton) {
    const sample = testMessages[nextTestMessage++ % testMessages.length];
    addMessage({
      nick: sample.displayName.toLowerCase(),
      displayName: sample.displayName,
      displayColor: "#8b5cf6",
      userId: `local-preview-${nextTestMessage}`,
      msgId: `preview-${Date.now()}`,
      badges: sample.badges,
      emotes: [],
      text: sample.text
    });
    return;
  }

  if (listener === "delete-message") {
    removeByAttribute("msgid", event.msgId);
    return;
  }

  if (listener === "delete-messages") {
    removeByAttribute("sender", event.userId, true);
    return;
  }

  if (listener !== "message") return;

  const data = event.data || event;
  const nickname = String(data.nick || data.displayName || "").toLowerCase();
  const text = String(data.text || "");

  if (fields.hideCommands === "yes" && text.trimStart().startsWith("!")) return;
  if (ignoredUsers.has(nickname)) return;

  addMessage(data);
});

function addMessage(data) {
  const previousPositions = capturePositions();
  const badges = Array.isArray(data.badges) ? data.badges : [];
  const role = getRole(badges);
  const row = document.createElement("div");
  row.className = `chat-row role-${role}`;
  if (role === "broadcaster") row.classList.add("is-broadcaster");
  row.dataset.msgid = String(data.msgId || data.tags?.id || crypto.randomUUID());
  row.dataset.sender = String(data.userId || data.tags?.["user-id"] || "");

  applyRoleTheme(row, role);

  const identity = document.createElement("div");
  identity.className = "identity";

  const username = document.createElement("span");
  username.className = "username";
  username.textContent = data.displayName || data.nick || "Anonyme";
  identity.append(username);

  if (fields.showBadges !== "no" && badges.length) {
    const badgeContainer = document.createElement("span");
    badgeContainer.className = "badges";
    for (const badge of badges) {
      if (!badge?.url) continue;
      const image = document.createElement("img");
      image.className = "badge";
      image.src = badge.url;
      image.alt = badge.description || badge.type || "Badge Twitch";
      image.title = image.alt;
      badgeContainer.append(image);
    }
    if (badgeContainer.childElementCount) identity.append(badgeContainer);
  }

  const bubble = document.createElement("div");
  bubble.className = "message-bubble";

  const content = document.createElement("span");
  content.className = "message-content";
  renderMessage(content, data);
  bubble.append(content);

  const tone = getToneAsset(String(data.text || ""));
  if (tone && fields.showTone !== "no") {
    const image = document.createElement("img");
    image.className = "tone";
    image.src = tone.url;
    image.alt = tone.label;
    bubble.append(image);
  }

  row.append(identity, bubble);
  chat.append(row);

  trimToLimit();
  animateStack(previousPositions, row);
  scheduleRemoval(row);
}

function getRole(badges) {
  const types = new Set(badges.map((badge) => badge?.type));
  if (types.has("broadcaster")) return "broadcaster";
  if (types.has("moderator")) return "moderator";
  if (types.has("vip")) return "vip";
  if (types.has("artist-badge")) return "artist";
  return "viewer";
}

function applyRoleTheme(element, role) {
  const fieldsByRole = {
    viewer: ["viewerColor", "viewerColor2"],
    moderator: ["moderatorColor", "moderatorColor2"],
    vip: ["vipColor", "vipColor2"],
    artist: ["artistColor", "artistColor2"],
    broadcaster: ["broadcasterColor", "broadcasterColor2"]
  };
  const defaults = {
    viewer: ["#5900FF", "#FF1BDF"],
    moderator: ["#2ABDFF", "#00FE9F"],
    vip: ["#FF1BDF", "#FF4D9D"],
    artist: ["#2ABDFF", "#78BEFF"],
    broadcaster: ["#E91916", "#FF4D6D"]
  };
  const [startField, endField] = fieldsByRole[role];
  const start = fields[startField] || defaults[role][0];
  const end = fields[endField] || defaults[role][1];
  const identityBgOpacity = clampOpacity(fields.identityBackgroundOpacity, 0.7);
  const identityBorderOpacity = clampOpacity(fields.identityBorderOpacity, 0.76);
  const messageBorderOpacity = clampOpacity(fields.messageBorderOpacity, 0.76);
  const glowOpacity = clampOpacity(fields.glowOpacity, 0.45);

  element.style.setProperty("--role-start", start);
  element.style.setProperty("--role-end", end);
  element.style.setProperty("--role-start-soft", mixWithDark(start, 0.85, identityBgOpacity));
  element.style.setProperty("--role-end-soft", mixWithDark(end, 0.72, identityBgOpacity));
  element.style.setProperty("--identity-border", toRgba(end, identityBorderOpacity));
  element.style.setProperty("--message-border", toRgba(end, messageBorderOpacity));
  element.style.setProperty("--glow-color", toRgba(end, glowOpacity));
}

function applyGlobalTheme() {
  const opacity = clampOpacity(fields.messageBackgroundOpacity, 0.7);
  const root = document.documentElement;
  root.style.setProperty("--bubble-background-alpha", toRgba(fields.bubbleBackground || "#161225", opacity));
  root.style.setProperty("--bubble-background-2-alpha", toRgba(fields.bubbleBackground2 || "#231A3D", opacity));
}

function clampOpacity(value, fallback) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.min(1, Math.max(0, number / 100)) : fallback;
}

function toRgba(color, alpha) {
  const match = String(color).trim().match(/^#([0-9a-f]{6})$/i);
  if (!match) return color;
  const value = Number.parseInt(match[1], 16);
  return `rgba(${value >> 16}, ${(value >> 8) & 255}, ${value & 255}, ${alpha})`;
}

function mixWithDark(color, amount, alpha = 1) {
  const foreground = String(color).trim().match(/^#([0-9a-f]{6})$/i);
  if (!foreground) return color;
  const value = Number.parseInt(foreground[1], 16);
  const dark = [18, 14, 35];
  const source = [value >> 16, (value >> 8) & 255, value & 255];
  const mixed = source.map((channel, index) => Math.round(dark[index] + (channel - dark[index]) * amount));
  return `rgba(${mixed.join(", ")}, ${alpha})`;
}

function renderMessage(container, data) {
  const text = String(data.text || "");
  const emotes = (Array.isArray(data.emotes) ? data.emotes : [])
    .filter((emote) => Number.isFinite(Number(emote.start)) && Number.isFinite(Number(emote.end)))
    .sort((a, b) => Number(a.start) - Number(b.start));

  if (!emotes.length) {
    appendNamedEmotes(container, text, Array.isArray(data.emotes) ? data.emotes : []);
    return;
  }

  let cursor = 0;
  for (const emote of emotes) {
    const start = Number(emote.start);
    const end = Number(emote.end);
    if (start < cursor || end < start) continue;
    container.append(document.createTextNode(text.slice(cursor, start)));
    container.append(createEmoteImage(emote));
    cursor = end + 1;
  }
  container.append(document.createTextNode(text.slice(cursor)));

  const remainingText = text.replaceAll(/\s/g, "");
  const emoteNames = emotes.map((emote) => emote.name || "").join("");
  if (remainingText === emoteNames) container.classList.add("is-emote-only");
}

function appendNamedEmotes(container, text, emotes) {
  const byName = new Map(emotes.filter((emote) => emote?.name).map((emote) => [emote.name, emote]));
  const parts = text.split(/(\s+)/);
  let hasText = false;
  let hasEmote = false;

  for (const part of parts) {
    const emote = byName.get(part);
    if (emote) {
      container.append(createEmoteImage(emote));
      hasEmote = true;
    } else {
      container.append(document.createTextNode(part));
      if (part.trim()) hasText = true;
    }
  }

  if (hasEmote && !hasText) container.classList.add("is-emote-only");
}

function createEmoteImage(emote) {
  const image = document.createElement("img");
  image.className = "emote";
  image.src = emote.urls?.[2] || emote.urls?.[1] || emote.url || "";
  image.alt = emote.name || "Emote";
  image.title = image.alt;
  return image;
}

function getToneAsset(text) {
  const trimmed = text.trim();
  if (trimmed.endsWith("!?") || trimmed.endsWith("?!")) {
    return { url: fields.mixedMarksImage, label: "Exclamation et interrogation" };
  }
  if (trimmed.endsWith("!")) return { url: fields.exclamationImage, label: "Exclamation" };
  if (trimmed.endsWith("?")) return { url: fields.questionImage, label: "Interrogation" };
  return null;
}

function trimToLimit() {
  const limit = Math.max(1, Number(fields.maxMessages) || 20);
  while (chat.childElementCount > limit) chat.firstElementChild?.remove();

  const gap = Number.parseFloat(getComputedStyle(chat).rowGap) || 0;
  const totalHeight = () => {
    const rows = [...chat.children];
    return rows.reduce((sum, row) => sum + row.getBoundingClientRect().height, 0) +
      Math.max(0, rows.length - 1) * gap;
  };

  while (chat.childElementCount > 1 && totalHeight() > chat.clientHeight) {
    chat.firstElementChild?.remove();
  }
}

function capturePositions() {
  return new Map([...chat.children].map((row) => [row, row.getBoundingClientRect().top]));
}

function animateStack(previousPositions, newRow) {
  window.requestAnimationFrame(() => {
    const duration = Math.max(0, Number(fields.animationDuration) || 520);
    for (const row of chat.children) {
      if (row === newRow || !previousPositions.has(row)) continue;
      const deltaY = previousPositions.get(row) - row.getBoundingClientRect().top;
      if (Math.abs(deltaY) < 0.5) continue;
      row.animate(
        [
          { transform: `translateY(${deltaY}px)` },
          { transform: "translateY(0)" }
        ],
        {
          duration,
          easing: "cubic-bezier(0.4, 0, 0.2, 1)"
        }
      );
    }
  });
}

function scheduleRemoval(row) {
  const seconds = Number(fields.hideAfter);
  if (!Number.isFinite(seconds) || seconds <= 0 || seconds === 999) return;
  window.setTimeout(() => removeRow(row), seconds * 1000);
}

function removeByAttribute(attribute, value, all = false) {
  if (value === undefined || value === null) return;
  const matches = [...chat.children].filter((row) => row.dataset[attribute] === String(value));
  for (const row of all ? matches : matches.slice(0, 1)) removeRow(row);
}

function removeRow(row) {
  if (!row?.isConnected || row.classList.contains("is-leaving")) return;
  row.classList.add("is-leaving");
  const duration = Math.max(0, Number(fields.animationDuration) || 520);
  window.setTimeout(() => {
    const previousPositions = capturePositions();
    row.remove();
    animateStack(previousPositions);
  }, duration + 40);
}

window.addEventListener("resize", trimToLimit);
document.fonts?.ready.then(trimToLimit);

preview.css:
:root {
	--w: 400px;
	--h: 46px;
	--radius: 23px;
	--reveal: 6px;
	--border-color: #ffffff;
	--border-width: 1px;
	--bg: linear-gradient(135deg, #161225, #231a3d);
	--accent: #571bc3;
	--text: rgba(255, 255, 255, 1);
	--text-muted: rgba(255, 255, 255, .65);
	--font: "Poppins";
	--textWeight: 500;
	--textSize: 14px;
}

html,
body {
	width: 100%;
	height: 100%;
	margin: 0;
	padding: 0;
	background: transparent;
	overflow: hidden;
}

body {
	display: flex;
	align-items: center;
	justify-content: center;
}

@keyframes playerEnter {
	from { opacity: 0; transform: translateY(12px) scale(.96); }
	to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes playerExit {
	from { opacity: 1; transform: translateY(0) scale(1); }
	to { opacity: 0; transform: translateY(12px) scale(.96); }
}

@keyframes playerSwap {
	0% { opacity: 0; transform: translateY(6px); }
	100% { opacity: 1; transform: translateY(0); }
}

@keyframes playerCoverSwap {
	0% { opacity: 0; transform: scale(.85) rotate(-6deg); }
	60% { opacity: 1; transform: scale(1.05) rotate(2deg); }
	100% { opacity: 1; transform: scale(1) rotate(0deg); }
}

@keyframes playerMarquee {
	0%, 15% { transform: translateX(0); }
	85%, 100% { transform: translateX(var(--scroll)); }
}

/* Même construction que la goal bar : pilule au-dessus, croissant de progression qui dépasse dessous */
.player {
	position: relative;
	width: var(--w);
	height: calc(var(--h) + var(--reveal));
	/* Compense le croissant qui dépasse dessous : c'est la pilule qui doit être au centre */
	margin-top: var(--reveal);
	flex: 0 0 auto;
	box-sizing: border-box;
	font-family: var(--font), system-ui, -apple-system, Segoe UI, Roboto, Arial;
	line-height: 1.15;
	color: var(--text);
	animation: playerEnter 520ms cubic-bezier(.2, .9, .2, 1) both;
}

.player-info {
	position: absolute;
	left: 0;
	top: 0;
	z-index: 2;
	width: 100%;
	height: var(--h);
	box-sizing: border-box;
	display: flex;
	align-items: center;
	gap: 8px;
	padding: 5px 18px 5px 5px;
	border-radius: var(--radius);
	border: var(--border-width) solid var(--border-color);
	background: var(--bg);
	backdrop-filter: blur(3px);
	overflow: hidden;
}

.player.is-hidden {
	animation: playerExit 420ms cubic-bezier(.4, 0, .8, .2) forwards;
}

/* Pas d'animation de sortie au tout premier rendu */
.player.is-hidden.is-initial {
	animation: none;
	opacity: 0;
}

.player-cover {
	position: relative;
	flex: 0 0 auto;
	height: 100%;
	aspect-ratio: 1;
	border-radius: calc(var(--radius) - 5px);
	overflow: hidden;
	background: rgba(255, 255, 255, .08);
	display: flex;
	align-items: center;
	justify-content: center;
}

.player-cover.is-swapping {
	animation: playerCoverSwap 560ms cubic-bezier(.34, 1.56, .64, 1);
}

.player-cover-img {
	position: absolute;
	inset: 0;
	width: 100%;
	height: 100%;
	object-fit: cover;
	opacity: 0;
	transition: opacity 300ms ease;
}

.player-cover-img.is-loaded {
	opacity: 1;
}

.player-cover-fallback {
	color: var(--text-muted);
	font-size: 20px;
	font-variation-settings: "FILL" 1, "wght" 200, "GRAD" 0, "opsz" 24;
}

.player.no-cover .player-cover {
	display: none;
}

.player.no-cover .player-info {
	padding-left: 18px;
}

.player-body {
	flex: 1 1 auto;
	min-width: 0;
	display: flex;
	flex-direction: column;
	justify-content: center;
	gap: 1px;
}

.player-body.is-swapping .player-line {
	animation: playerSwap 420ms cubic-bezier(.2, .9, .2, 1) both;
}

.player-line {
	overflow: hidden;
	white-space: nowrap;
	font-size: var(--textSize);
}

.player-scroll {
	display: inline-block;
	padding-right: 0;
}

.player-scroll.is-overflowing {
	animation: playerMarquee var(--scroll-duration, 8s) ease-in-out infinite alternate;
}

.player-title {
	font-weight: var(--textWeight);
}

.player-sep {
	margin: 0 .45em;
	color: var(--text-muted);
}

.player-artist {
	font-weight: 400;
	color: var(--text-muted);
}

.player-sep.is-empty,
.player-artist.is-empty {
	display: none;
}

/* Fenêtre qui révèle le croissant (pleine largeur, découpé en JS) de gauche à droite */
.player-progress {
	position: absolute;
	left: 0;
	top: calc(var(--h) - 18px);
	z-index: 1;
	width: 0%;
	height: 24px;
	overflow: hidden;
	box-sizing: border-box;
	transition: width 500ms linear;
}

.player-progress.no-transition {
	transition: none;
}

.player.no-progress .player-progress {
	display: none;
}

.player-fill {
	position: absolute;
	left: 0;
	top: 0;
	height: 24px;
	background: var(--accent);
	transition: background 400ms ease;
}

.player-error {
	display: none;
	position: absolute;
	inset: 0;
	align-items: center;
	justify-content: center;
	padding: 0 24px;
	background: rgba(20, 10, 30, .92);
	color: #ffb4c8;
	font-size: 12px;
	text-align: center;
}

.player.has-error .player-error {
	display: flex;
}

preview.js:
function clamp(n, min, max){ return Math.max(min, Math.min(max, n)); }
function num(v){
  const s = String(v ?? "").trim().replace(",", ".");
  const n = Number(s.replace(/[^\d.-]/g,''));
  return Number.isFinite(n) ? n : 0;
}

const SPOTIFY_TOKEN_URL = "https://accounts.spotify.com/api/token";
const SPOTIFY_PLAYER_URL = "https://api.spotify.com/v1/me/player/currently-playing?additional_types=track,episode";

let SETTINGS = {};
let EDITOR_MODE = false;

// État de lecture courant (null = rien à afficher)
// { id, title, artist, cover, durationMs, progressMs, isPlaying, syncedAt }
let NOW = null;
let lastTrackId = null;
let isVisible = false;

let pollTimer = null;
let tickTimer = null;
let bootId = 0;

let accessToken = null;
let accessTokenExpiresAt = 0;

// ------------------------------------
// Google Fonts
// ------------------------------------
function setGoogleFont(family){
  const link = document.getElementById("googleFontLink");
  if (!link) return;

  const name = String(family || "Poppins").trim();
  const urlName = name.replace(/\s+/g, "+");
  link.href = `https://fonts.googleapis.com/css2?family=${urlName}:wght@300;400;500;600;700;800&display=swap`;
  document.documentElement.style.setProperty("--font", `"${name}"`);
}

// ------------------------------------
// Couleurs
// ------------------------------------
function isHexColor(v){
  const s = String(v ?? "").trim();
  if (!/^#[0-9a-f]+$/i.test(s)) return false;
  const len = s.length - 1;
  return len === 3 || len === 6 || len === 8;
}
function normalizeColorValue(v){
  const s = String(v ?? "").trim();
  if (!s) return null;
  if (isHexColor(s)){
    const hex = s.slice(1);
    if (hex.length === 3) return "#" + hex.split("").map(c => c + c).join("");
    if (hex.length === 8) return "#" + hex.slice(0, 6);
    return "#" + hex;
  }
  if (/^(rgb|hsl)a?\(/i.test(s)) return s;
  return null;
}
function hexOr(v, fallback){
  return normalizeColorValue(v) ?? fallback;
}
function hexToRgb(hexValue){
  const clean = String(hexValue ?? "#ffffff").trim().replace("#", "");
  const full = clean.length === 3 ? clean.split("").map(c => c + c).join("") : clean;
  const n = parseInt(full, 16);
  if (full.length !== 6 || !Number.isFinite(n)) return { r: 255, g: 255, b: 255 };
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}
function toRgba(hexValue, alpha){
  const { r, g, b } = hexToRgb(hexValue);
  return `rgba(${r}, ${g}, ${b}, ${clamp(alpha, 0, 1)})`;
}
function buildPaint(type, color1, color2, angle, alpha){
  const c1 = toRgba(color1, alpha);
  const c2 = toRgba(color2, alpha);
  return type === "gradient" ? `linear-gradient(${angle}deg, ${c1}, ${c2})` : c1;
}

// ------------------------------------
// Normalisation du fieldData
// ------------------------------------
function oneOf(v, allowed, fallback){
  const s = String(v ?? "").toLowerCase();
  return allowed.includes(s) ? s : fallback;
}

function normalizeFields(raw){
  if (Array.isArray(raw)){
    raw = Object.fromEntries(raw.filter(field => field?.name).map(field => [field.name, field.value]));
  }
  raw = raw || {};

  return {
    spotify_client_id: String(raw.spotify_client_id ?? "").trim(),
    spotify_client_secret: String(raw.spotify_client_secret ?? "").trim(),
    spotify_refresh_token: String(raw.spotify_refresh_token ?? "").trim(),
    poll_interval: clamp(num(raw.poll_interval ?? 5) || 5, 2, 60),
    hide_when_paused: oneOf(raw.hide_when_paused, ["hide", "show"], "hide"),
    demo_mode: oneOf(raw.demo_mode, ["auto", "always", "never"], "auto"),

    show_cover: oneOf(raw.show_cover, ["yes", "no"], "yes"),
    show_progress: oneOf(raw.show_progress, ["yes", "no"], "yes"),

    font_family: String(raw.font_family ?? "Poppins"),
    font_weight: String(raw.font_weight ?? "600"),
    text_size: num(raw.text_size ?? 14),
    width: num(raw.width ?? 400),
    height: num(raw.height ?? 46),
    corner_radius: num(raw.corner_radius ?? -1),

    text_color: hexOr(raw.text_color, "#ffffff"),
    accent_color: hexOr(raw.accent_color, "#571bc3"),
    border_color: hexOr(raw.border_color, "#ffffff"),
    border_width: Math.max(0, num(raw.border_width ?? 1)),
    border_opacity: clamp(num(raw.border_opacity ?? 1), 0, 1),
    background_type: oneOf(raw.background_type, ["solid", "gradient"], "gradient"),
    background_color1: hexOr(raw.background_color1, "#161225"),
    background_color2: hexOr(raw.background_color2, "#231a3d"),
    background_opacity: clamp(num(raw.background_opacity ?? 1), 0, 1)
  };
}

function hasCredentials(){
  return Boolean(SETTINGS.spotify_client_id && SETTINGS.spotify_client_secret && SETTINGS.spotify_refresh_token);
}

function isDemo(){
  if (SETTINGS.demo_mode === "always") return true;
  if (SETTINGS.demo_mode === "never") return false;
  // "auto" : uniquement dans l'éditeur, jamais de faux morceaux en live
  return EDITOR_MODE && !hasCredentials();
}

// ------------------------------------
// Apparence
// ------------------------------------
function applyStyle(){
  const root = document.documentElement.style;
  const s = SETTINGS;

  setGoogleFont(s.font_family);
  root.setProperty("--textWeight", s.font_weight);
  if (s.text_size > 0) root.setProperty("--textSize", s.text_size + "px");

  const h = s.height > 0 ? s.height : 46;
  root.setProperty("--w", s.width > 0 ? s.width + "px" : "100%");
  root.setProperty("--h", h + "px");
  root.setProperty("--radius", (s.corner_radius >= 0 ? s.corner_radius : h / 2) + "px");

  root.setProperty("--text", s.text_color);
  root.setProperty("--text-muted", toRgba(s.text_color, .65));
  root.setProperty("--accent", s.accent_color);
  root.setProperty("--border-color", toRgba(s.border_color, s.border_opacity));
  root.setProperty("--border-width", s.border_width + "px");
  root.setProperty("--bg", buildPaint(s.background_type, s.background_color1, s.background_color2, 135, s.background_opacity));

  const player = document.getElementById("player");
  player.classList.toggle("no-cover", s.show_cover === "no");
  player.classList.toggle("no-progress", s.show_progress === "no");

  fillShapeWidth = 0;
  ensureFillShape();
}

// ------------------------------------
// Rendu
// ------------------------------------
function restartClass(el, cls){
  if (!el) return;
  el.classList.remove(cls);
  void el.offsetWidth;
  el.classList.add(cls);
}

// Fait défiler un texte trop long dans sa ligne (aller-retour)
function updateMarquee(el){
  if (!el) return;
  el.classList.remove("is-overflowing");
  el.style.removeProperty("--scroll");

  requestAnimationFrame(() => {
    const overflow = el.scrollWidth - el.parentElement.clientWidth;
    if (overflow <= 2) return;
    el.style.setProperty("--scroll", `-${overflow + 4}px`);
    el.style.setProperty("--scroll-duration", `${clamp(overflow / 25, 4, 14)}s`);
    el.classList.add("is-overflowing");
  });
}

function setCover(url){
  const img = document.getElementById("cover");
  if (!img) return;
  if (!url){
    img.removeAttribute("src");
    img.classList.remove("is-loaded");
    return;
  }
  if (img.getAttribute("src") === url) return;
  img.classList.remove("is-loaded");
  img.onload = () => img.classList.add("is-loaded");
  img.onerror = () => img.classList.remove("is-loaded");
  img.src = url;
}

function currentProgress(){
  if (!NOW) return 0;
  const elapsed = NOW.isPlaying ? Date.now() - NOW.syncedAt : 0;
  return clamp(NOW.progressMs + elapsed, 0, NOW.durationMs || Infinity);
}

// ------------------------------------
// Forme du croissant (même tracé que la goal bar, mis à l'échelle)
// ------------------------------------
function buildCrescentPath(totalWidthPx, totalHeightPx){
  const s = totalHeightPx / 24;
  const n = (v) => +(v * s).toFixed(3);
  const capW = n(21);
  const rightStart = +(totalWidthPx - capW).toFixed(3);

  return (
    `M${rightStart},${n(18)}` +
    `H${capW}` +
    `C${n(10.47)},${n(18)} ${n(1.71)},${n(10.14)} ${n(0.24)},0` +
    `c${n(-0.14)},${n(0.98)} ${n(-0.24)},${n(1.98)} ${n(-0.24)},${n(3)}` +
    `c0,${n(11.55)} ${n(9.45)},${n(21)} ${n(21)},${n(21)}` +
    `H${rightStart}` +
    `c${n(11.55)},0 ${n(21)},${n(-9.45)} ${n(21)},${n(-21)}` +
    `c0,${n(-1.02)} ${n(-0.1)},${n(-2.02)} ${n(-0.24)},${n(-3)}` +
    `c${n(-1.47)},${n(10.14)} ${n(-10.23)},${n(18)} ${n(-20.76)},${n(18)}` +
    `Z`
  );
}

let fillObserverStarted = false;
let fillShapeWidth = 0;

// Le croissant occupe toute la largeur du lecteur ; seule la fenêtre qui le révèle change de largeur
function applyFillShape(){
  const fillEl = document.getElementById("fill");
  const playerEl = document.getElementById("player");
  if (!fillEl || !playerEl) return false;

  const fullWidthPx = playerEl.clientWidth;
  if (!fullWidthPx || fullWidthPx < 10) return false;
  if (fullWidthPx === fillShapeWidth) return true;

  fillShapeWidth = fullWidthPx;
  fillEl.style.width = fullWidthPx + "px";
  fillEl.style.clipPath = `path("${buildCrescentPath(fullWidthPx, 24)}")`;
  return true;
}

function ensureFillShape(){
  if (!applyFillShape()) requestAnimationFrame(applyFillShape);

  if (!fillObserverStarted && typeof ResizeObserver !== "undefined"){
    fillObserverStarted = true;
    new ResizeObserver(() => applyFillShape()).observe(document.getElementById("player"));
  }
}

function renderProgress(instant){
  if (!NOW) return;
  const progress = currentProgress();
  const pct = NOW.durationMs > 0 ? (progress / NOW.durationMs) * 100 : 0;

  const progressWindow = document.getElementById("progressWindow");
  progressWindow.classList.toggle("no-transition", Boolean(instant));
  progressWindow.style.width = clamp(pct, 0, 100) + "%";
}

function setVisible(visible){
  const player = document.getElementById("player");
  if (visible === isVisible) return;
  isVisible = visible;
  player.classList.remove("is-initial");
  if (visible){
    player.classList.remove("is-hidden");
  } else {
    player.classList.add("is-hidden");
  }
}

function render(){
  const player = document.getElementById("player");

  const shouldShow = Boolean(NOW) && (NOW.isPlaying || SETTINGS.hide_when_paused === "show");
  if (!NOW){
    setVisible(false);
    return;
  }

  player.classList.toggle("is-paused", !NOW.isPlaying);

  if (NOW.id !== lastTrackId){
    const changed = lastTrackId !== null;
    lastTrackId = NOW.id;

    const artistEl = document.getElementById("artist");
    document.getElementById("title").textContent = NOW.title;
    artistEl.textContent = NOW.artist;
    artistEl.classList.toggle("is-empty", !NOW.artist);
    document.getElementById("sep").classList.toggle("is-empty", !NOW.artist);
    setCover(NOW.cover);

    if (changed && isVisible){
      restartClass(document.querySelector(".player-body"), "is-swapping");
      restartClass(document.getElementById("coverWrap"), "is-swapping");
    }

    renderProgress(true);
    updateMarquee(document.getElementById("trackLine"));
  } else {
    renderProgress(false);
  }

  setVisible(shouldShow);
}

function showError(message){
  const player = document.getElementById("player");
  const errorEl = document.getElementById("error");
  console.warn("[Music player]", message);

  // L'erreur n'est affichée que dans l'éditeur : en live, le lecteur se masque simplement
  if (!EDITOR_MODE){
    NOW = null;
    render();
    return;
  }
  errorEl.textContent = message;
  player.classList.add("has-error");
  setVisible(true);
}

function clearError(){
  document.getElementById("player").classList.remove("has-error");
}

// ------------------------------------
// Spotify Web API
// ------------------------------------
async function getAccessToken(force){
  if (!force && accessToken && Date.now() < accessTokenExpiresAt) return accessToken;

  const body = new URLSearchParams({
    grant_type: "refresh_token",
    refresh_token: SETTINGS.spotify_refresh_token
  });

  const res = await fetch(SPOTIFY_TOKEN_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      Authorization: "Basic " + btoa(`${SETTINGS.spotify_client_id}:${SETTINGS.spotify_client_secret}`)
    },
    body
  });

  const data = await res.json().catch(() => ({}));
  if (!res.ok || !data.access_token){
    const reason = data.error_description || data.error || `HTTP ${res.status}`;
    const err = new Error(`Authentification Spotify refusée : ${reason}. Vérifiez Client ID, Client Secret et refresh token.`);
    err.fatal = res.status === 400 || res.status === 401;
    throw err;
  }

  accessToken = data.access_token;
  accessTokenExpiresAt = Date.now() + (num(data.expires_in) || 3600) * 1000 - 60000;
  return accessToken;
}

function parsePlayback(data){
  const item = data?.item;
  if (!item) return null;

  const isEpisode = item.type === "episode";
  const images = (isEpisode ? item.images || item.show?.images : item.album?.images) || [];
  // Les images sont triées de la plus grande à la plus petite : on prend la plus petite >= 160px
  const cover = [...images].reverse().find(img => (img.width || 0) >= 160)?.url || images[0]?.url || "";

  return {
    id: item.id || item.uri || `${item.name}`,
    title: item.name || "",
    artist: isEpisode
      ? (item.show?.name || "")
      : (item.artists || []).map(a => a.name).filter(Boolean).join(", "),
    cover,
    durationMs: num(item.duration_ms),
    progressMs: num(data.progress_ms),
    isPlaying: Boolean(data.is_playing),
    syncedAt: Date.now()
  };
}

async function fetchNowPlaying(retried){
  const token = await getAccessToken(false);
  const res = await fetch(SPOTIFY_PLAYER_URL, { headers: { Authorization: `Bearer ${token}` } });

  if (res.status === 204) return { playback: null };
  if (res.status === 401 && !retried){
    accessToken = null;
    return fetchNowPlaying(true);
  }
  if (res.status === 429){
    return { playback: NOW, retryAfter: num(res.headers.get("Retry-After")) || 30 };
  }
  if (!res.ok){
    const data = await res.json().catch(() => ({}));
    const err = new Error(`Spotify : ${data?.error?.message || `HTTP ${res.status}`}`);
    err.fatal = res.status === 403;
    throw err;
  }

  const data = await res.json().catch(() => null);
  return { playback: parsePlayback(data) };
}

function schedulePoll(seconds, id){
  clearTimeout(pollTimer);
  pollTimer = setTimeout(() => poll(id), seconds * 1000);
}

async function poll(id){
  if (id !== bootId) return;

  try {
    const result = await fetchNowPlaying(false);
    if (id !== bootId) return;
    clearError();
    NOW = result.playback;
    render();
    schedulePoll(result.retryAfter || SETTINGS.poll_interval, id);
  } catch (err){
    if (id !== bootId) return;
    showError(err?.message || String(err));
    // Identifiants invalides : inutile de marteler l'API, on réessaie lentement
    schedulePoll(err?.fatal ? 60 : Math.max(SETTINGS.poll_interval, 10), id);
  }
}

// ------------------------------------
// Mode démo (aucun identifiant : aperçu dans le labo / l'éditeur)
// ------------------------------------
function demoCover(c1, c2){
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">` +
    `<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1">` +
    `<stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/>` +
    `</linearGradient></defs><rect width="100" height="100" fill="url(#g)"/>` +
    `<circle cx="50" cy="50" r="22" fill="none" stroke="#fff" stroke-opacity=".5" stroke-width="2"/>` +
    `<circle cx="50" cy="50" r="5" fill="#fff" fill-opacity=".7"/></svg>`;
  return "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
}

const DEMO_TRACKS = [
  { title: "Midnight City", artist: "M83", durationMs: 243000, cover: demoCover("#571bc3", "#ff4d8d") },
  { title: "Une chanson avec un titre beaucoup trop long pour tenir sur une ligne", artist: "Artiste démo, Featuring quelqu'un", durationMs: 32000, cover: demoCover("#2abdff", "#161225") },
  { title: "Instant Crush", artist: "Daft Punk, Julian Casablancas", durationMs: 337000, cover: demoCover("#ff1bdf", "#231a3d") }
];
let demoIndex = 0;

function demoStep(id){
  if (id !== bootId) return;

  const track = DEMO_TRACKS[demoIndex % DEMO_TRACKS.length];
  // Démarre près de la fin pour voir rapidement l'enchaînement des morceaux
  const startAt = Math.max(0, track.durationMs - 20000);
  NOW = { id: `demo-${demoIndex}`, ...track, progressMs: startAt, isPlaying: true, syncedAt: Date.now() };
  render();

  clearTimeout(pollTimer);
  pollTimer = setTimeout(() => {
    demoIndex += 1;
    demoStep(id);
  }, track.durationMs - startAt);
}

// ------------------------------------
// Init
// ------------------------------------
function startTicker(){
  clearInterval(tickTimer);
  tickTimer = setInterval(() => {
    if (NOW && NOW.isPlaying && isVisible) renderProgress(false);
  }, 500);
}

async function detectEditorMode(){
  try {
    const status = await window.SE_API?.getOverlayStatus?.();
    EDITOR_MODE = Boolean(status?.isEditorMode);
  } catch (_){
    EDITOR_MODE = false;
  }
}

function boot(rawFieldData){
  bootId += 1;
  const id = bootId;
  clearTimeout(pollTimer);

  const previous = SETTINGS;
  SETTINGS = normalizeFields(rawFieldData);

  const credentialsChanged =
    previous.spotify_client_id !== SETTINGS.spotify_client_id ||
    previous.spotify_client_secret !== SETTINGS.spotify_client_secret ||
    previous.spotify_refresh_token !== SETTINGS.spotify_refresh_token;
  if (credentialsChanged){
    accessToken = null;
    accessTokenExpiresAt = 0;
  }

  NOW = null;
  lastTrackId = null;
  clearError();
  applyStyle();
  startTicker();

  if (isDemo()){
    demoIndex = 0;
    demoStep(id);
    return;
  }

  if (!hasCredentials()){
    showError("Renseignez Client ID, Client Secret et refresh token Spotify dans les champs du widget.");
    return;
  }

  poll(id);
}

window.addEventListener("onWidgetLoad", async (obj) => {
  await detectEditorMode();
  boot(obj?.detail?.fieldData || {});
});

window.addEventListener("onWidgetUpdate", (obj) => {
  boot(obj?.detail?.fieldData || {});
});
